/**
 * Resolves a relative asset path against `window.DEAD_CELLS_ASSET_BASE` when set
 * (e.g. when running standalone via jsDelivr).
 */
export function resolveAssetUrl(path: string): string {
  const base = (window as unknown as { DEAD_CELLS_ASSET_BASE?: string }).DEAD_CELLS_ASSET_BASE;
  if (!base) return path;
  return base.replace(/\/+$/, "") + "/" + path.replace(/^\/+/, "");
}
